 * (closed where open is needed, reopening an open one, the open-milestone cap,
 * a taken name). Mapped to `conflict` by `toAppError`.
 */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly reason: "closed" | "already_open" | "too_many_open" | "name_taken",
    message?: string,
  ) {
    super(message ?? `Milestone conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

/** Names are unique per project ignoring letter case and surrounding spaces. */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

export function isMilestoneOpen(milestone: Pick<Milestone, "closedAt">): boolean {
  return milestone.closedAt === null;
}

/** Open, target date strictly in the past, and still holding open issues. */
export function isMilestoneOverdue(
  milestone: Pick<Milestone, "closedAt" | "targetDate">,
  openIssues: number,
  now: Date,
): boolean {
  if (milestone.closedAt !== null || milestone.targetDate === null) return false;
  if (openIssues <= 0) return false;
  return Date.parse(milestone.targetDate) < now.getTime();
}

function targetTime(targetDate: IsoTimestamp | null): number {
  return targetDate === null ? Number.POSITIVE_INFINITY : Date.parse(targetDate);
}

/**
 * Listing order: open before closed, then earliest target date first with
 * undated milestones last. Equal keys compare 0, so a stable sort over rows
 * already in creation order keeps oldest first.
 */
export function compareMilestones(
  a: Pick<Milestone, "closedAt" | "targetDate">,
  b: Pick<Milestone, "closedAt" | "targetDate">,
): number {
  const aClosed = a.closedAt !== null ? 1 : 0;
  const bClosed = b.closedAt !== null ? 1 : 0;
  if (aClosed !== bClosed) return aClosed - bClosed;

  const at = targetTime(a.targetDate);
  const bt = targetTime(b.targetDate);
  if (at === bt) return 0;
  return at < bt ? -1 : 1;
}
