cat > src/server/repositories/milestone-repository.ts <<'EOF'
/**
 * Milestone rows and the issue bookkeeping that moves with them.
 *
 * Every state-dependent write (name uniqueness, the open cap, closing with its
 * issue moves, putting an issue into a milestone) runs its check and its write
 * in one synchronous transaction, so two concurrent calls cannot both pass a
 * check the other invalidates. Refusals come back as values; the service maps
 * them onto domain errors.
 *
 * Must call (do not reimplement): livePredicate, orgPredicate
 */
import { and, asc, count, eq, inArray, isNull, notInArray, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { milestoneNameKey } from "@/lib/milestones";
import { getDb, issues, milestones } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { toIsoTimestamp } from "@/types/common";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { toIssue, toMilestone } from "./_mappers";
import type {
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type {
  IssueId,
  MilestoneId,
  OrgId,
  ProjectId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Milestone, MilestoneProgress } from "@/types/milestone";

type Db = ReturnType<typeof getDb>;
type Tx = Parameters<Parameters<Db["transaction"]>[0]>[0];

export type MilestoneWriteResult =
  | { readonly ok: true; readonly milestone: Milestone }
  | {
      readonly ok: false;
      readonly reason: "name_taken" | "too_many_open" | "already_open" | "closed";
    };

export type CloseMilestoneResult =
  | {
      readonly ok: true;
      readonly milestone: Milestone;
      readonly movedIssueIds: readonly IssueId[];
    }
  | {
      readonly ok: false;
      readonly reason: "closed" | "target_not_found" | "target_closed";
    };

export type AssignabilityResult = "ok" | "not_found" | "closed";

export type SetIssueMilestoneResult =
  | { readonly ok: true; readonly issue: Issue }
  | { readonly ok: false; readonly reason: "issue_not_found" | "not_found" | "closed" };

export async function findMilestoneById(
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone | null> {
  const row = getDb()
    .select()
    .from(milestones)
    .where(
      and(orgPredicate(milestones.orgId, orgId), eq(milestones.id, milestoneId)),
    )
    .get();
  return row ? toMilestone(row) : null;
}

/** Every milestone of a project, closed ones included, oldest first. */
export async function listMilestonesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Milestone[]> {
  const rows = getDb()
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .orderBy(asc(milestones.createdAt), sql`${milestones}.rowid`)
    .all();
  return rows.map(toMilestone);
}

/** Live-issue counts per milestone; milestones without issues map to zeros. */
export async function getMilestoneProgress(
  orgId: OrgId,
  milestoneIds: readonly MilestoneId[],
): Promise<ReadonlyMap<MilestoneId, MilestoneProgress>> {
  const progress = new Map<MilestoneId, MilestoneProgress>(
    milestoneIds.map((id) => [id, { total: 0, open: 0, closed: 0 }]),
  );
  if (milestoneIds.length === 0) return progress;

  const rows = getDb()
    .select({
      milestoneId: issues.milestoneId,
      status: issues.status,
      value: count(),
    })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          inArray(issues.milestoneId, [...milestoneIds]),
        ),
      ),
    )
    .groupBy(issues.milestoneId, issues.status)
    .all();

  for (const row of rows) {
    const id = row.milestoneId as MilestoneId | null;
    const current = id === null ? undefined : progress.get(id);
    if (id === null || current === undefined) continue;

    const isClosed = CLOSED_ISSUE_STATUSES.includes(row.status);
    progress.set(id, {
      total: current.total + row.value,
      open: current.open + (isClosed ? 0 : row.value),
      closed: current.closed + (isClosed ? row.value : 0),
    });
  }

  return progress;
}

function projectMilestones(
  tx: Tx | Db,
  orgId: OrgId,
  projectId: ProjectId,
): readonly Milestone[] {
  return tx
    .select()
    .from(milestones)
    .where(
      and(
        orgPredicate(milestones.orgId, orgId),
        eq(milestones.projectId, projectId),
      ),
    )
    .all()
    .map(toMilestone);
}

function isNameTaken(
  all: readonly Milestone[],
  name: string,
  exceptId: MilestoneId | null,
): boolean {
  const key = milestoneNameKey(name);
  return all.some(
    (m) => m.id !== exceptId && milestoneNameKey(m.name) === key,
  );
}

function openCount(all: readonly Milestone[]): number {
  return all.filter((m) => m.closedAt === null).length;
}

export async function insertMilestone(
  input: CreateMilestoneInput,
  maxOpen: number,
