import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { emit } from "@/lib/event-bus";
import { isMilestoneOverdue, MilestoneStateError, compareMilestones } from "@/lib/milestones";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as milestoneRepo from "@/server/repositories/milestone-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  NotFoundError,
  projectResource,
  requireFound,
} from "./_support";
import { notify } from "./notification-service";
import type {
  CloseMilestoneInput,
  CreateMilestoneInput,
  UpdateMilestoneInput,
} from "@/schemas/milestone";
import type { IssueId, MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Milestone, MilestoneWithProgress } from "@/types/milestone";
import type { Project } from "@/types/project";

/** Loads a project and applies the write gates shared by every milestone write. */
async function loadWritableProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);
  return project;
}

/** Loads a milestone together with its project, gated for a write. */
async function loadWritableMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<{ milestone: Milestone; project: Project }> {
  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = await loadWritableProject(actor, orgId, milestone.projectId);
  return { milestone, project };
}

function refuse(reason: Parameters<typeof describeRefusal>[0]): never {
  throw new MilestoneStateError(reason, describeRefusal(reason));
}

function describeRefusal(
  reason: "closed" | "already_open" | "too_many_open" | "name_taken",
): string {
  switch (reason) {
    case "closed":
      return "The milestone is closed";
    case "already_open":
      return "The milestone is already open";
    case "too_many_open":
      return `A project may hold at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones`;
    case "name_taken":
      return "Another milestone in this project already has that name";
  }
}

export async function createMilestone(
  actor: Actor,
  input: CreateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const project = await loadWritableProject(actor, input.orgId, input.projectId);

  const result = await milestoneRepo.insertMilestone(
    input,
    MAX_OPEN_MILESTONES_PER_PROJECT,
  );
  if (!result.ok) refuse(result.reason);

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: project.id,
  });

  return result.milestone;
}

export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const { milestone } = await loadWritableMilestone(
    actor,
    input.orgId,
    input.milestoneId,
  );

  const result = await milestoneRepo.updateMilestone(milestone, input);
  if (!result.ok) refuse(result.reason);
  return result.milestone;
}

