  const result = await milestoneRepo.closeMilestone(current, target);
  if (!result.ok) {
    if (result.reason === "target_not_found") {
      throw new NotFoundError("Milestone", target ?? "");
    }
    refuse("closed");
  }

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: project.id,
    movedToMilestoneId: target,
    movedIssueIds: result.movedIssueIds,
  });

  for (const issueId of result.movedIssueIds) {
    const issue = await issueRepo.findIssueById(input.orgId, issueId);
    if (issue === null || issue.assigneeId === null) continue;

    await notify(input.orgId, "issue_milestone_changed", [issue.assigneeId], {
      title: "An issue changed milestone",
      body:
        target === null
          ? `Issue ${issueId} was taken out of milestone ${result.milestone.name}`
          : `Issue ${issueId} was moved out of milestone ${result.milestone.name}`,
      href: `/issues/${issueId}`,
      actorId: actor.userId,
    });
  }

  return { milestone: result.milestone, movedIssueIds: result.movedIssueIds };
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  assertOrgScope(actor, orgId);
  const { milestone, project } = await loadWritableMilestone(
    actor,
    orgId,
    milestoneId,
  );

  const result = await milestoneRepo.reopenMilestone(
    milestone,
    MAX_OPEN_MILESTONES_PER_PROJECT,
  );
  if (!result.ok) refuse(result.reason);

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: result.milestone.id,
    projectId: project.id,
  });

  return result.milestone;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const rows = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  const progress = await milestoneRepo.getMilestoneProgress(
    orgId,
    rows.map((m) => m.id),
  );

  const now = new Date();
  return [...rows]
    .sort(compareMilestones)
    .map((milestone) => withProgress(milestone, progress.get(milestone.id), now));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const progress = await milestoneRepo.getMilestoneProgress(orgId, [milestone.id]);
  return withProgress(milestone, progress.get(milestone.id), new Date());
}

function withProgress(
  milestone: Milestone,
  progress: { total: number; open: number; closed: number } | undefined,
  now: Date,
): MilestoneWithProgress {
  const counts = progress ?? { total: 0, open: 0, closed: 0 };
  return {
    milestone,
    progress: counts,
    overdue: isMilestoneOverdue(milestone, counts.open, now),
  };
}
