  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  assertOrgScope(actor, input.orgId);
  const { milestone } = await loadWritableMilestone(
    actor,
    input.orgId,
    input.milestoneId,
  );

  const result = await milestoneRepo.updateMilestone(milestone, input);
  if (!result.ok) refuse(result.reason);
  return result.milestone;
}

/**
 * Closing moves the milestone's open live issues to `moveOpenIssuesTo` (or out
 * of any milestone) in one transaction, then announces the close and tells each
 * moved issue's assignee — never the person who closed it.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);
  const { milestone: current, project } = await loadWritableMilestone(
    actor,
    input.orgId,
    input.milestoneId,
  );

  const target = input.moveOpenIssuesTo ?? null;
  if (current.closedAt !== null) refuse("closed");

  const result = await milestoneRepo.closeMilestone(current, target);
  if (!result.ok) {
    if (result.reason === "target_not_found") {
      throw new NotFoundError("Milestone", target ?? "");
    }
    refuse("closed");
  }

