  Milestone,
  MilestoneProgress,
  MilestoneWithProgress,
} from "@/types/milestone";
import type { Project } from "@/types/project";

type RefusalReason = MilestoneStateError["reason"];

function describeRefusal(reason: RefusalReason): string {
  switch (reason) {
    case "closed":
      return "The milestone is closed";
    case "already_open":
      return "The milestone is already open";
    case "too_many_open":
      return `A project may hold at most ${MAX_OPEN_MILESTONES_PER_PROJECT} open milestones`;
