  const progress = await milestoneRepo.getMilestoneProgress(
    orgId,
    rows.map((m) => m.id),
  );

  const now = new Date();
  // Rows arrive oldest first and the sort is stable, so ties keep that order.
  return [...rows]
    .sort(compareMilestones)
    .map((milestone) => withProgress(milestone, progress.get(milestone.id), now));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
