import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as projectService from "@/server/services/project-service";
import { registerActivityListeners, listActivity } from "@/server/services/activity-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("miles");
  other = await createTenant("miles2");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

const past = "2020-01-01T00:00:00.000Z" as IsoTimestamp;

function create(name: string, targetDate: IsoTimestamp | null = null, t = tenant) {
  return milestoneService.createMilestone(t.actors.member, {
    orgId: t.org.id,
    projectId: t.project.id,
    name,
    targetDate,
  });
}

describe("services/milestone-service", () => {
  it("creates, renames and enforces unique names ignoring case and spaces", async () => {
    const events: unknown[] = [];
    const off = subscribe("milestone.created", (p) => void events.push(p));
    const m = await create("Alpha");
    off();
    expect(events).toHaveLength(1);

    await expect(create("  ALPHA ")).rejects.toMatchObject({ reason: "name_taken" });
    await expect(create("alpha", null, other)).resolves.toBeDefined();

    const renamed = await milestoneService.updateMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      milestoneId: m.id,
      name: "ALPHA",
    });
    expect(renamed.name).toBe("ALPHA");

    const rows = await listActivity(tenant.actors.admin, {
      orgId: tenant.org.id,
      action: ["milestone.created"],
      limit: 10,
    });
    expect(rows.items[0]?.subjectKind).toBe("milestone");
    expect(rows.items[0]?.subjectId).toBe(m.id);
  });

  it("guards permission, tenant and project existence", async () => {
    await expect(
      milestoneService.createMilestone(tenant.actors.viewer, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        name: "nope",
        targetDate: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      milestoneService.listMilestones(tenant.actors.member, other.org.id, other.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, other.project.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.listMilestones(tenant.actors.viewer, tenant.org.id, tenant.project.id),
    ).resolves.toBeDefined();
  });

  it("caps open milestones and lets closed ones go uncounted", async () => {
    const t = await createTenant("milecap");
    const made = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      made.push(await create(`m${i}`, null, t));
    }
    await expect(create("one-too-many", null, t)).rejects.toMatchObject({
      reason: "too_many_open",
    });

    await milestoneService.closeMilestone(t.actors.member, {
      orgId: t.org.id,
      milestoneId: made[0]!.id,
      moveOpenIssuesTo: null,
    });
    const extra = await create("one-more", null, t);
    await expect(
      milestoneService.reopenMilestone(t.actors.member, t.org.id, made[0]!.id),
    ).rejects.toMatchObject({ reason: "too_many_open" });
    await expect(
      milestoneService.reopenMilestone(t.actors.member, t.org.id, extra.id),
    ).rejects.toMatchObject({ reason: "already_open" });
  });

  it("closes, moves open live issues, alerts assignees once and orders the list", async () => {
    const t = await createTenant("mileclose");
    const a = await create("A", past, t);
    const b = await create("B", null, t);

    const mk = async (title: string, assigneeId: typeof t.userIds.admin | null, ms: typeof a.id | null) =>
      issueService.createIssue(t.actors.member, {
        ...issueInput(t.org.id, t.project.id, { title, assigneeId }),
        milestoneId: ms,
      });
    const i1 = await mk("Issue one", t.userIds.admin, a.id);
    const i2 = await mk("Issue two", t.userIds.member, a.id);
    const i3 = await mk("Issue three", null, a.id);
    const done = await mk("Issue done", t.userIds.admin, a.id);
    await issueService.changeIssueStatus(t.actors.member, {
      orgId: t.org.id,
      issueId: done.id,
      status: "done",
    });

    const before = await milestoneService.getMilestone(t.actors.viewer, t.org.id, a.id);
    expect(before.progress).toEqual({ total: 4, open: 3, closed: 1 });
    expect(before.overdue).toBe(true);

    await expect(
      milestoneService.closeMilestone(t.actors.member, {
        orgId: t.org.id,
        milestoneId: a.id,
        moveOpenIssuesTo: a.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      milestoneService.closeMilestone(t.actors.member, {
        orgId: t.org.id,
        milestoneId: a.id,
        moveOpenIssuesTo: b.id,
      }).then(() => null),
    ).resolves.toBeNull();

    const result = await issueService.getIssue(t.actors.viewer, t.org.id, i1.id);
    expect(result.issue.milestoneId).toBe(b.id);
    expect((await issueService.getIssue(t.actors.viewer, t.org.id, i3.id)).issue.milestoneId).toBe(b.id);
    expect((await issueService.getIssue(t.actors.viewer, t.org.id, done.id)).issue.milestoneId).toBe(a.id);
    void i2;

    const adminAlerts = await listNotifications(t.actors.owner, {
      orgId: t.org.id,
      recipientId: t.userIds.admin,
      unreadOnly: false,
      kind: ["issue_milestone_changed"],
      limit: 10,
    });
    expect(adminAlerts.items).toHaveLength(1);

    await expect(
      milestoneService.closeMilestone(t.actors.member, {
        orgId: t.org.id,
        milestoneId: a.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const list = await milestoneService.listMilestones(t.actors.viewer, t.org.id, t.project.id);
    expect(list.map((x) => x.milestone.name)).toEqual(["B", "A"]);
    expect(list[0]?.progress).toEqual({ total: 3, open: 3, closed: 0 });
    expect(list[0]?.overdue).toBe(false);
  });

  it("moves issues between milestones and refuses closed, foreign and archived", async () => {
    const t = await createTenant("milemove");
    const a = await create("A", null, t);
    const closed = await create("Closed", null, t);
    await milestoneService.closeMilestone(t.actors.member, {
      orgId: t.org.id,
      milestoneId: closed.id,
      moveOpenIssuesTo: null,
    });
    const foreign = await create("Foreign", null, other);

    await expect(
      issueService.createIssue(t.actors.member, {
        ...issueInput(t.org.id, t.project.id, { title: "bad create" }),
        milestoneId: closed.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const issue = await issueService.createIssue(t.actors.member, {
      ...issueInput(t.org.id, t.project.id, { title: "good create" }),
      milestoneId: a.id,
    });
    expect(issue.milestoneId).toBe(a.id);

    await expect(
      issueService.setIssueMilestone(t.actors.member, {
        orgId: t.org.id,
        issueId: issue.id,
        milestoneId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      issueService.setIssueMilestone(t.actors.member, {
        orgId: t.org.id,
        issueId: issue.id,
        milestoneId: closed.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    const out = await issueService.setIssueMilestone(t.actors.member, {
      orgId: t.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(out.milestoneId).toBeNull();

    await projectService.archiveProject(t.actors.admin, {
      orgId: t.org.id,
      projectId: t.project.id,
      archiveIssues: false,
    });
    await expect(create("late", null, t)).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      issueService.setIssueMilestone(t.actors.member, {
        orgId: t.org.id,
        issueId: issue.id,
        milestoneId: a.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      milestoneService.listMilestones(t.actors.viewer, t.org.id, t.project.id),
    ).resolves.toHaveLength(2);
  });
});
